insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Membrane transport: Active and co-transport', 'In active transport a solute is moved against a concentration or electrochemical gradient; in doing so the transport proteins involved consume metabolic energy, usually ATP. In primary active transport the hydrolysis of the energy provider (e.g. ATP) takes place directly in order to transport the solute in question, for instance, when the transport proteins are ATPase enzymes. Where the hydrolysis of the energy provider is indirect as is the case in secondary active transport, use is made of the energy stored in an electrochemical gradient. For example, in co-transport use is made of the gradients of certain solutes to transport a target compound against its gradient, causing the dissipation of the solute gradient. It may appear that, in this example, there is no energy use, but hydrolysis of the energy provider is required to establish the gradient of the solute transported along with the target compound. The gradient of the co-transported solute will be generated through the use of certain types of proteins called biochemical pumps.', 'Wikipedia: Membrane transport', 'https://en.wikipedia.org/w/index.php?title=Membrane_transport&oldid=1314166694', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'In active transport a solute is moved against a concentration or electrochemical gradient; in doing so the transport proteins involved consume metabolic energy, usually ATP. In primary active transport the hydrolysis of the energy provider (e.g. ATP) takes place directly in order to transport the solute in question, for instance, when the transport proteins are ATPase enzymes. Where the hydrolysis of the energy provider is indirect as is the case in secondary active transport, use is made of the energy stored in an electrochemical gradient. For example, in co-transport use is made of the gradients of certain solutes to transport a target compound against its gradient, causing the dissipation of the solute gradient. It may appear that, in this example, there is no energy use, but hydrolysis of the energy provider is required to establish the gradient of the solute transported along with the target compound. The gradient of the co-transported solute will be generated through the use of certain types of proteins called biochemical pumps.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Membrane transport: Active and co-transport', 'The discovery of the existence of this type of transporter protein came from the study of the kinetics of cross-membrane molecule transport. For certain solutes it was noted that the transport velocity reached a plateau at a particular concentration above which there was no significant increase in uptake rate, indicating a log curve type response. This was interpreted as showing that transport was mediated by the formation of a substrate-transporter complex, which is conceptually the same as the enzyme-substrate complex of enzyme kinetics. Therefore, each transport protein has an affinity constant for a solute that is equal to the concentration of the solute when the transport velocity is half its maximum value. This is equivalent in the case of an enzyme to the Michaelis–Menten constant. Some important features of active transport in addition to its ability to intervene even against a gradient, its kinetics and the use of ATP, are its high selectivity and ease of selective pharmacological inhibition', 'Wikipedia: Membrane transport', 'https://en.wikipedia.org/w/index.php?title=Membrane_transport&oldid=1314166694', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The discovery of the existence of this type of transporter protein came from the study of the kinetics of cross-membrane molecule transport. For certain solutes it was noted that the transport velocity reached a plateau at a particular concentration above which there was no significant increase in uptake rate, indicating a log curve type response. This was interpreted as showing that transport was mediated by the formation of a substrate-transporter complex, which is conceptually the same as the enzyme-substrate complex of enzyme kinetics. Therefore, each transport protein has an affinity constant for a solute that is equal to the concentration of the solute when the transport velocity is half its maximum value. This is equivalent in the case of an enzyme to the Michaelis–Menten constant. Some important features of active transport in addition to its ability to intervene even against a gradient, its kinetics and the use of ATP, are its high selectivity and ease of selective pharmacological inhibition');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Organelle', 'An organelle is a specialized subunit, within a biological cell, that has a specific function. The name organelle comes from the idea that these structures are parts of cells, as organs are to the body, hence organelle, the suffix -elle being a diminutive. Organelles are either separately enclosed within their own lipid bilayers (also called membrane-bound organelles) or are spatially distinct functional units without a surrounding lipid bilayer (non-membrane bounded organelles). Although most organelles are functional units within cells, some functional units that extend outside of cells are often termed organelles, such as cilia, the flagellum and archaellum, and the trichocyst (these could be referred to as membrane bound in the sense that they are attached to (or bound to) the membrane).', 'Wikipedia: Organelle', 'https://en.wikipedia.org/w/index.php?title=Organelle&oldid=1379206593', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'An organelle is a specialized subunit, within a biological cell, that has a specific function. The name organelle comes from the idea that these structures are parts of cells, as organs are to the body, hence organelle, the suffix -elle being a diminutive. Organelles are either separately enclosed within their own lipid bilayers (also called membrane-bound organelles) or are spatially distinct functional units without a surrounding lipid bilayer (non-membrane bounded organelles). Although most organelles are functional units within cells, some functional units that extend outside of cells are often termed organelles, such as cilia, the flagellum and archaellum, and the trichocyst (these could be referred to as membrane bound in the sense that they are attached to (or bound to) the membrane).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Organelle', 'Organelles are identified by microscopy, and can also be purified by cell fractionation. There are many types of organelles, particularly in eukaryotic cells. They include structures that make up the endomembrane system (such as the nuclear envelope, endoplasmic reticulum, and Golgi apparatus), and other structures such as mitochondria and plastids. While prokaryotes do not possess eukaryotic organelles, some do contain protein-shelled bacterial microcompartments, which are thought to act as primitive prokaryotic organelles; and there is also evidence of other membrane-bounded structures. Also, the prokaryotic flagellum which protrudes outside the cell, and its motor, as well as the largely extracellular pilus, are often spoken of as organelles.', 'Wikipedia: Organelle', 'https://en.wikipedia.org/w/index.php?title=Organelle&oldid=1379206593', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Organelles are identified by microscopy, and can also be purified by cell fractionation. There are many types of organelles, particularly in eukaryotic cells. They include structures that make up the endomembrane system (such as the nuclear envelope, endoplasmic reticulum, and Golgi apparatus), and other structures such as mitochondria and plastids. While prokaryotes do not possess eukaryotic organelles, some do contain protein-shelled bacterial microcompartments, which are thought to act as primitive prokaryotic organelles; and there is also evidence of other membrane-bounded structures. Also, the prokaryotic flagellum which protrudes outside the cell, and its motor, as well as the largely extracellular pilus, are often spoken of as organelles.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Organelle: History and terminology', 'In biology, organs are defined as confined functional units within an organism. The analogy of bodily organs to microscopic cellular substructures is obvious, as from even early works, authors of respective textbooks rarely elaborate on the distinction between the two. In the 1830s, Félix Dujardin refuted Ehrenberg''s theory that microorganisms have the same organs as multicellular animals, only smaller. Credited as the first to use a diminutive of organ (i.e., little organ) for cellular structures was German zoologist Karl August Möbius (1884), who used the term organula (plural of organulum, the diminutive of Latin organum). In a footnote, which was published as a correction in the next issue of the journal, he justified his suggestion to call organs of unicellular organisms "organella" since they are only differently formed parts of one cell, in contrast to multicellular organs of multicellular organisms.', 'Wikipedia: Organelle', 'https://en.wikipedia.org/w/index.php?title=Organelle&oldid=1379206593', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'In biology, organs are defined as confined functional units within an organism. The analogy of bodily organs to microscopic cellular substructures is obvious, as from even early works, authors of respective textbooks rarely elaborate on the distinction between the two. In the 1830s, Félix Dujardin refuted Ehrenberg''s theory that microorganisms have the same organs as multicellular animals, only smaller. Credited as the first to use a diminutive of organ (i.e., little organ) for cellular structures was German zoologist Karl August Möbius (1884), who used the term organula (plural of organulum, the diminutive of Latin organum). In a footnote, which was published as a correction in the next issue of the journal, he justified his suggestion to call organs of unicellular organisms "organella" since they are only differently formed parts of one cell, in contrast to multicellular organs of multicellular organisms.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Organelle: Types', 'In the broadest definition, an organelle is any part of the cell that acts as a distinct functional unit. This includes membrane-bound as well as non-membrane-bound, or membrane-less organelles. In a more restrictive definition, only membrane-bound ones are included. In the most restrictive definition, only the endosymbiotic membrane-bound ones are included. The membrane-bound organelles include the endosymbiotic (mitochondria and plastids) and components formed by the endomembrane system such as the lysosome. An endomembrane system and mitochondria are found in almost all eukaryotes. Plants, algae, and some protists additionally have chloroplasts. A very small minority of bacteria also have a sort-of endomembrane system. The membrane-less organelles (MLOs), also called biomolecular complexes, are large assemblies of macromolecules that carry out particular and specialized functions, but are membrane-less. Many of these are referred to as "proteinaceous organelles" as their main structure is made of proteins. MLOs include: large protein complexes: proteasome, DNA polymerase III holoenzyme, RNA polymerase II holoenzyme, symmetric viral capsids, complex of GroEL and GroES; membrane protein complexes: porosome, photosystem I, ATP synthase The mechanisms by which such non-membrane bounded organelles form and retain their spatial integrity have been likened to liquid-liquid phase separation.', 'Wikipedia: Organelle', 'https://en.wikipedia.org/w/index.php?title=Organelle&oldid=1379206593', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'In the broadest definition, an organelle is any part of the cell that acts as a distinct functional unit. This includes membrane-bound as well as non-membrane-bound, or membrane-less organelles. In a more restrictive definition, only membrane-bound ones are included. In the most restrictive definition, only the endosymbiotic membrane-bound ones are included. The membrane-bound organelles include the endosymbiotic (mitochondria and plastids) and components formed by the endomembrane system such as the lysosome. An endomembrane system and mitochondria are found in almost all eukaryotes. Plants, algae, and some protists additionally have chloroplasts. A very small minority of bacteria also have a sort-of endomembrane system. The membrane-less organelles (MLOs), also called biomolecular complexes, are large assemblies of macromolecules that carry out particular and specialized functions, but are membrane-less. Many of these are referred to as "proteinaceous organelles" as their main structure is made of proteins. MLOs include: large protein complexes: proteasome, DNA polymerase III holoenzyme, RNA polymerase II holoenzyme, symmetric viral capsids, complex of GroEL and GroES; membrane protein complexes: porosome, photosystem I, ATP synthase The mechanisms by which such non-membrane bounded organelles form and retain their spatial integrity have been likened to liquid-liquid phase separation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Organelle: Eukaryotic organelles', 'Eukaryotic cells are structurally complex, and by definition are organized, in part, by interior compartments that are themselves enclosed by lipid membranes that resemble the outermost cell membrane. The larger organelles, such as the nucleus and vacuoles, are easily visible with the light microscope. They were among the first biological discoveries made after the invention of the microscope. Not all eukaryotic cells have each of the organelles listed below. Exceptional organisms have cells that do not include some organelles (such as mitochondria) that might otherwise be considered universal to eukaryotes. The several plastids including chloroplasts are distributed among some but not all eukaryotes. There are also occasional exceptions to the number of membranes surrounding organelles, listed in the tables below (e.g., some that are listed as double-membrane are sometimes found with single or triple membranes). In addition, the number of individual organelles of each type found in a given cell varies depending upon the function of that cell. The cell membrane and cell wall are not organelles.', 'Wikipedia: Organelle', 'https://en.wikipedia.org/w/index.php?title=Organelle&oldid=1379206593', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Eukaryotic cells are structurally complex, and by definition are organized, in part, by interior compartments that are themselves enclosed by lipid membranes that resemble the outermost cell membrane. The larger organelles, such as the nucleus and vacuoles, are easily visible with the light microscope. They were among the first biological discoveries made after the invention of the microscope. Not all eukaryotic cells have each of the organelles listed below. Exceptional organisms have cells that do not include some organelles (such as mitochondria) that might otherwise be considered universal to eukaryotes. The several plastids including chloroplasts are distributed among some but not all eukaryotes. There are also occasional exceptions to the number of membranes surrounding organelles, listed in the tables below (e.g., some that are listed as double-membrane are sometimes found with single or triple membranes). In addition, the number of individual organelles of each type found in a given cell varies depending upon the function of that cell. The cell membrane and cell wall are not organelles.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Organelle: Prokaryotic organelles', 'Prokaryotes are not as structurally complex as eukaryotes, and were once thought to have little internal organization, and lack cellular compartments and internal membranes; but slowly, details are emerging about prokaryotic internal structures that overturn these assumptions. An early false turn was the idea developed in the 1970s that bacteria might contain cell membrane folds termed mesosomes, but these were later shown to be artifacts produced by the chemicals used to prepare the cells for electron microscopy. However, there is increasing evidence of compartmentalization in at least some prokaryotes. Research has revealed that at least some bacteria have microcompartments, such as carboxysomes. These subcellular compartments are 100–200 nm in diameter and are enclosed by a shell of proteins. Even more striking is the description of membrane-bound magnetosomes in magnetotactic bacteria, reported in 2006. The bacterial phylum Planctomycetota has revealed a number of compartmentalization features. The Planctomycetota cell plan includes intracytoplasmic membranes that separates the cytoplasm into paryphoplasm (an outer ribosome-free space) and pirellulosome (or riboplasm, an inner ribosome-containing space). Membrane-bounded anammoxosomes have been discovered in five Planctomycetota "anammox" genera, which perform anaerobic ammonium oxidation. In the Planctomycetota species Gemmata obscuriglobus, a nucleus-like structure surrounded by lipid membranes has been reported.', 'Wikipedia: Organelle', 'https://en.wikipedia.org/w/index.php?title=Organelle&oldid=1379206593', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Prokaryotes are not as structurally complex as eukaryotes, and were once thought to have little internal organization, and lack cellular compartments and internal membranes; but slowly, details are emerging about prokaryotic internal structures that overturn these assumptions. An early false turn was the idea developed in the 1970s that bacteria might contain cell membrane folds termed mesosomes, but these were later shown to be artifacts produced by the chemicals used to prepare the cells for electron microscopy. However, there is increasing evidence of compartmentalization in at least some prokaryotes. Research has revealed that at least some bacteria have microcompartments, such as carboxysomes. These subcellular compartments are 100–200 nm in diameter and are enclosed by a shell of proteins. Even more striking is the description of membrane-bound magnetosomes in magnetotactic bacteria, reported in 2006. The bacterial phylum Planctomycetota has revealed a number of compartmentalization features. The Planctomycetota cell plan includes intracytoplasmic membranes that separates the cytoplasm into paryphoplasm (an outer ribosome-free space) and pirellulosome (or riboplasm, an inner ribosome-containing space). Membrane-bounded anammoxosomes have been discovered in five Planctomycetota "anammox" genera, which perform anaerobic ammonium oxidation. In the Planctomycetota species Gemmata obscuriglobus, a nucleus-like structure surrounded by lipid membranes has been reported.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Organelle: Prokaryotic organelles', 'Compartmentalization is a feature of prokaryotic photosynthetic structures. Purple bacteria have "chromatophores", which are reaction centers found in invaginations of the cell membrane. Green sulfur bacteria have chlorosomes, which are photosynthetic antenna complexes found bonded to cell membranes. Cyanobacteria have internal thylakoid membranes for light-dependent photosynthesis; studies have revealed that the cell membrane and the thylakoid membranes are not continuous with each other. Advances in synthetic biology have enabled the construction of artificial bacterial organelles that are more reminiscent to eukaryotic ones, including structures formed through liquid-liquid phase separation of "RNA organelle" reported in 2017. These RNA systems termed TEARS is capable of regulating compartmentalize cellular processes, scaffolding and sequestering metabolic pathways. These synthetic organelles can be repurposed as their eukaryotic counterparts, to isolate purify proteins within prokaryotes, enabling a technology termed PandaPure for chromatography-free purification.', 'Wikipedia: Organelle', 'https://en.wikipedia.org/w/index.php?title=Organelle&oldid=1379206593', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Compartmentalization is a feature of prokaryotic photosynthetic structures. Purple bacteria have "chromatophores", which are reaction centers found in invaginations of the cell membrane. Green sulfur bacteria have chlorosomes, which are photosynthetic antenna complexes found bonded to cell membranes. Cyanobacteria have internal thylakoid membranes for light-dependent photosynthesis; studies have revealed that the cell membrane and the thylakoid membranes are not continuous with each other. Advances in synthetic biology have enabled the construction of artificial bacterial organelles that are more reminiscent to eukaryotic ones, including structures formed through liquid-liquid phase separation of "RNA organelle" reported in 2017. These RNA systems termed TEARS is capable of regulating compartmentalize cellular processes, scaffolding and sequestering metabolic pathways. These synthetic organelles can be repurposed as their eukaryotic counterparts, to isolate purify proteins within prokaryotes, enabling a technology termed PandaPure for chromatography-free purification.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton', 'The cytoskeleton is a complex, dynamic network of interlinking protein filaments present in the cytoplasm of all cells, including those of bacteria and archaea. In eukaryotes, it extends from the cell nucleus to the cell membrane and is composed of similar proteins in the various organisms. It is composed of three main components: microfilaments, intermediate filaments, and microtubules, and these are all capable of rapid growth and/or disassembly depending on the cell''s requirements.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The cytoskeleton is a complex, dynamic network of interlinking protein filaments present in the cytoplasm of all cells, including those of bacteria and archaea. In eukaryotes, it extends from the cell nucleus to the cell membrane and is composed of similar proteins in the various organisms. It is composed of three main components: microfilaments, intermediate filaments, and microtubules, and these are all capable of rapid growth and/or disassembly depending on the cell''s requirements.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton', 'The cytoskeleton can perform many functions. Its primary function is to give the cell its shape and mechanical resistance to deformation, and through association with extracellular connective tissue and other cells it stabilizes entire tissues. The cytoskeleton can also contract, thereby deforming the cell and the cell''s environment and allowing cells to migrate. Moreover, it is involved in many cell signaling pathways and in the uptake of extracellular material (endocytosis), the segregation of chromosomes during cellular division, the cytokinesis stage of cell division, as scaffolding to organize the contents of the cell in space and in intracellular transport (for example, the movement of vesicles and organelles within the cell) and can be a template for the construction of a cell wall. Furthermore, it can form specialized structures, such as flagella, cilia, lamellipodia and podosomes. The structure, function and dynamic behavior of the cytoskeleton can be very different, depending on organism and cell type. Even within one cell, the cytoskeleton can change through association with other proteins and the previous history of the network.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The cytoskeleton can perform many functions. Its primary function is to give the cell its shape and mechanical resistance to deformation, and through association with extracellular connective tissue and other cells it stabilizes entire tissues. The cytoskeleton can also contract, thereby deforming the cell and the cell''s environment and allowing cells to migrate. Moreover, it is involved in many cell signaling pathways and in the uptake of extracellular material (endocytosis), the segregation of chromosomes during cellular division, the cytokinesis stage of cell division, as scaffolding to organize the contents of the cell in space and in intracellular transport (for example, the movement of vesicles and organelles within the cell) and can be a template for the construction of a cell wall. Furthermore, it can form specialized structures, such as flagella, cilia, lamellipodia and podosomes. The structure, function and dynamic behavior of the cytoskeleton can be very different, depending on organism and cell type. Even within one cell, the cytoskeleton can change through association with other proteins and the previous history of the network.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton', 'A large-scale example of an action performed by the cytoskeleton is muscle contraction. This is carried out by groups of highly specialized cells working together. A main component in the cytoskeleton that helps show the true function of this muscle contraction is the microfilament. Microfilaments are composed of the most abundant cellular protein known as actin. During contraction of a muscle, within each muscle cell, myosin molecular motors collectively exert forces on parallel actin filaments. Muscle contraction starts from nerve impulses which then causes increased amounts of calcium to be released from the sarcoplasmic reticulum. Increases in calcium in the cytosol allows muscle contraction to begin with the help of two proteins, tropomyosin and troponin. Tropomyosin inhibits the interaction between actin and myosin, while troponin senses the increase in calcium and releases the inhibition. This action contracts the muscle cell, and through the synchronous process in many muscle cells, the entire muscle.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'A large-scale example of an action performed by the cytoskeleton is muscle contraction. This is carried out by groups of highly specialized cells working together. A main component in the cytoskeleton that helps show the true function of this muscle contraction is the microfilament. Microfilaments are composed of the most abundant cellular protein known as actin. During contraction of a muscle, within each muscle cell, myosin molecular motors collectively exert forces on parallel actin filaments. Muscle contraction starts from nerve impulses which then causes increased amounts of calcium to be released from the sarcoplasmic reticulum. Increases in calcium in the cytosol allows muscle contraction to begin with the help of two proteins, tropomyosin and troponin. Tropomyosin inhibits the interaction between actin and myosin, while troponin senses the increase in calcium and releases the inhibition. This action contracts the muscle cell, and through the synchronous process in many muscle cells, the entire muscle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton: Eukaryotic cytoskeleton', 'Eukaryotic cells contain three main kinds of cytoskeletal filaments: microfilaments, microtubules, and intermediate filaments. In neurons the intermediate filaments are known as neurofilaments. Each type is formed by the polymerization of a distinct type of protein subunit and has its own characteristic shape and intracellular distribution. Microfilaments are polymers of the protein actin and are 7 nm in diameter. Microtubules are composed of tubulin and are 25 nm in diameter. Intermediate filaments are composed of various proteins, depending on the type of cell in which they are found; they are normally 8-12 nm in diameter. The cytoskeleton provides the cell with structure and shape, and by excluding macromolecules from some of the cytosol, it adds to the level of macromolecular crowding in this compartment. Cytoskeletal elements interact extensively and intimately with cellular membranes.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Eukaryotic cells contain three main kinds of cytoskeletal filaments: microfilaments, microtubules, and intermediate filaments. In neurons the intermediate filaments are known as neurofilaments. Each type is formed by the polymerization of a distinct type of protein subunit and has its own characteristic shape and intracellular distribution. Microfilaments are polymers of the protein actin and are 7 nm in diameter. Microtubules are composed of tubulin and are 25 nm in diameter. Intermediate filaments are composed of various proteins, depending on the type of cell in which they are found; they are normally 8-12 nm in diameter. The cytoskeleton provides the cell with structure and shape, and by excluding macromolecules from some of the cytosol, it adds to the level of macromolecular crowding in this compartment. Cytoskeletal elements interact extensively and intimately with cellular membranes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton: Eukaryotic cytoskeleton', 'Research into neurodegenerative disorders such as Parkinson''s disease, Alzheimer''s disease, Huntington''s disease, and amyotrophic lateral sclerosis (ALS) indicate that the cytoskeleton is affected in these diseases. Parkinson''s disease is marked by the degradation of neurons, resulting in tremors, rigidity, and other non-motor symptoms. Research has shown that microtubule assembly and stability in the cytoskeleton is compromised causing the neurons to degrade over time. In Alzheimer''s disease, tau proteins which stabilize microtubules malfunction in the progression of the illness causing pathology of the cytoskeleton. Excess glutamine in the Huntington protein (huntingtin) involved with linking vesicles onto the cytoskeleton is also proposed to be a factor in the development of Huntington''s Disease. Amyotrophic lateral sclerosis results in a loss of movement caused by the degradation of motor neurons, and also involves defects of the cytoskeleton. Stuart Hameroff and Roger Penrose suggest a role of microtubule vibrations in neurons in the origin of consciousness. Accessory proteins including motor proteins regulate and link the filaments to other cell compounds and each other and are essential for controlled assembly of cytoskeletal filaments in particular locations. A number of small-molecule cytoskeletal drugs have been discovered that interact with actin and microtubules. These compounds have proven useful in studying the cytoskeleton, and several have clinical applications.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Research into neurodegenerative disorders such as Parkinson''s disease, Alzheimer''s disease, Huntington''s disease, and amyotrophic lateral sclerosis (ALS) indicate that the cytoskeleton is affected in these diseases. Parkinson''s disease is marked by the degradation of neurons, resulting in tremors, rigidity, and other non-motor symptoms. Research has shown that microtubule assembly and stability in the cytoskeleton is compromised causing the neurons to degrade over time. In Alzheimer''s disease, tau proteins which stabilize microtubules malfunction in the progression of the illness causing pathology of the cytoskeleton. Excess glutamine in the Huntington protein (huntingtin) involved with linking vesicles onto the cytoskeleton is also proposed to be a factor in the development of Huntington''s Disease. Amyotrophic lateral sclerosis results in a loss of movement caused by the degradation of motor neurons, and also involves defects of the cytoskeleton. Stuart Hameroff and Roger Penrose suggest a role of microtubule vibrations in neurons in the origin of consciousness. Accessory proteins including motor proteins regulate and link the filaments to other cell compounds and each other and are essential for controlled assembly of cytoskeletal filaments in particular locations. A number of small-molecule cytoskeletal drugs have been discovered that interact with actin and microtubules. These compounds have proven useful in studying the cytoskeleton, and several have clinical applications.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton: Microfilaments', 'Microfilaments, also known as actin filaments, are composed of linear polymers of G-actin proteins, and generate force when the growing (plus) end of the filament pushes against a barrier, such as the cell membrane. They also act as tracks for the movement of myosin molecules that affix to the microfilament and "walk" along them. In general, the major component or protein of microfilaments are actin. The G-actin monomer combines to form a polymer which continues to form the microfilament (actin filament). These subunits then assemble into two chains that intertwine into what are called F-actin chains. Myosin motoring along F-actin filaments generates contractile forces in so-called actomyosin fibers, both in muscle as well as most non-muscle cell types. Actin structures are controlled by the Rho family of small GTP-binding proteins such as Rho itself for contractile acto-myosin filaments ("stress fibers"), Rac for lamellipodia and Cdc42 for filopodia.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Microfilaments, also known as actin filaments, are composed of linear polymers of G-actin proteins, and generate force when the growing (plus) end of the filament pushes against a barrier, such as the cell membrane. They also act as tracks for the movement of myosin molecules that affix to the microfilament and "walk" along them. In general, the major component or protein of microfilaments are actin. The G-actin monomer combines to form a polymer which continues to form the microfilament (actin filament). These subunits then assemble into two chains that intertwine into what are called F-actin chains. Myosin motoring along F-actin filaments generates contractile forces in so-called actomyosin fibers, both in muscle as well as most non-muscle cell types. Actin structures are controlled by the Rho family of small GTP-binding proteins such as Rho itself for contractile acto-myosin filaments ("stress fibers"), Rac for lamellipodia and Cdc42 for filopodia.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton: Intermediate filaments', 'Intermediate filaments are a part of the cytoskeleton of many eukaryotic cells. These filaments, averaging 10 nanometers in diameter, are more stable (strongly bound) than microfilaments, and heterogeneous constituents of the cytoskeleton. Like actin filaments, they function in the maintenance of cell-shape by bearing tension (microtubules, by contrast, resist compression but can also bear tension during mitosis and during the positioning of the centrosome). Intermediate filaments organize the internal tridimensional structure of the cell, anchoring organelles and serving as structural components of the nuclear lamina. They also participate in some cell-cell and cell-matrix junctions. Nuclear lamina exist in all animals and all tissues. Some animals like the fruit fly do not have any cytoplasmic intermediate filaments. In those animals that express cytoplasmic intermediate filaments, these are tissue specific. Keratin intermediate filaments in epithelial cells provide protection for different mechanical stresses the skin may endure. They also provide protection for organs against metabolic, oxidative, and chemical stresses. Strengthening of epithelial cells with these intermediate filaments may prevent onset of apoptosis, or cell death, by reducing the probability of stress.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Intermediate filaments are a part of the cytoskeleton of many eukaryotic cells. These filaments, averaging 10 nanometers in diameter, are more stable (strongly bound) than microfilaments, and heterogeneous constituents of the cytoskeleton. Like actin filaments, they function in the maintenance of cell-shape by bearing tension (microtubules, by contrast, resist compression but can also bear tension during mitosis and during the positioning of the centrosome). Intermediate filaments organize the internal tridimensional structure of the cell, anchoring organelles and serving as structural components of the nuclear lamina. They also participate in some cell-cell and cell-matrix junctions. Nuclear lamina exist in all animals and all tissues. Some animals like the fruit fly do not have any cytoplasmic intermediate filaments. In those animals that express cytoplasmic intermediate filaments, these are tissue specific. Keratin intermediate filaments in epithelial cells provide protection for different mechanical stresses the skin may endure. They also provide protection for organs against metabolic, oxidative, and chemical stresses. Strengthening of epithelial cells with these intermediate filaments may prevent onset of apoptosis, or cell death, by reducing the probability of stress.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cytoskeleton: Intermediate filaments', 'Intermediate filaments are most commonly known as the support system or "scaffolding" for the cell and nucleus while also playing a role in some cell functions. In combination with proteins and desmosomes, the intermediate filaments form cell-cell connections and anchor the cell-matrix junctions that are used in messaging between cells as well as vital functions of the cell. These connections allow the cell to communicate through the desmosome of multiple cells to adjust structures of the tissue based on signals from the cells environment. Mutations in the IF proteins have been shown to cause serious medical issues such as premature aging, desmin mutations compromising organs, Alexander Disease, and muscular dystrophy. made of vimentins. Vimentin intermediate filaments are in general present in mesenchymal cells. made of desmin, play an important role in structural and mechanical support of muscle cells.', 'Wikipedia: Cytoskeleton', 'https://en.wikipedia.org/w/index.php?title=Cytoskeleton&oldid=1380962901', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Intermediate filaments are most commonly known as the support system or "scaffolding" for the cell and nucleus while also playing a role in some cell functions. In combination with proteins and desmosomes, the intermediate filaments form cell-cell connections and anchor the cell-matrix junctions that are used in messaging between cells as well as vital functions of the cell. These connections allow the cell to communicate through the desmosome of multiple cells to adjust structures of the tissue based on signals from the cells environment. Mutations in the IF proteins have been shown to cause serious medical issues such as premature aging, desmin mutations compromising organs, Alexander Disease, and muscular dystrophy. made of vimentins. Vimentin intermediate filaments are in general present in mesenchymal cells. made of desmin, play an important role in structural and mechanical support of muscle cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle', 'The cell cycle, or cell-division cycle, is the sequence of events that take place in a cell and lead to its division into two daughter cells. These events include the growth of the cell, duplication of its DNA (DNA replication) and some of its organelles, and subsequently the partitioning of its cytoplasm, chromosomes and other components into two daughter cells in a process called cell division. In eukaryotic cells (having a cell nucleus) including animal, plant, fungal, and protist cells, the cell cycle is divided into two main stages: interphase, and the M phase that includes mitosis and cytokinesis. During interphase, the cell grows, accumulating nutrients needed for mitosis, and replicates its DNA and some of its organelles. Its successive stages differ in their specialized biochemical processes, preparing the cell for initiation of the cell''s division, but are not usually morphologically distinguishable. During the M phase, the replicated chromosomes, organelles, and cytoplasm separate into two new daughter cells. To ensure the proper replication of cellular components and division, cell cycle checkpoints follow each of the key stages of the cycle, controlling whether the cell progresses to the next.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The cell cycle, or cell-division cycle, is the sequence of events that take place in a cell and lead to its division into two daughter cells. These events include the growth of the cell, duplication of its DNA (DNA replication) and some of its organelles, and subsequently the partitioning of its cytoplasm, chromosomes and other components into two daughter cells in a process called cell division. In eukaryotic cells (having a cell nucleus) including animal, plant, fungal, and protist cells, the cell cycle is divided into two main stages: interphase, and the M phase that includes mitosis and cytokinesis. During interphase, the cell grows, accumulating nutrients needed for mitosis, and replicates its DNA and some of its organelles. Its successive stages differ in their specialized biochemical processes, preparing the cell for initiation of the cell''s division, but are not usually morphologically distinguishable. During the M phase, the replicated chromosomes, organelles, and cytoplasm separate into two new daughter cells. To ensure the proper replication of cellular components and division, cell cycle checkpoints follow each of the key stages of the cycle, controlling whether the cell progresses to the next.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle', 'In cells without nuclei (the prokaryotes: bacteria and archaea), the cell cycle is divided into the B, C, and D periods. The B period extends from the end of cell division to the beginning of DNA replication. DNA replication occurs during the C period. The D period refers to the stage between the end of DNA replication and the splitting of the bacterial cell into two daughter cells. In single-celled organisms, a single cell-division cycle is how the organism reproduces. In multicellular organisms such as plants and animals, a series of cell-division cycles is how the organism develops from a single-celled fertilized egg into a mature organism, and is also the process by which hair, skin, blood cells, and some internal organs are regenerated and healed (with the possible exception of nerves; see nerve damage). After cell division, each of the daughter cells begins the interphase of a new cell cycle.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'In cells without nuclei (the prokaryotes: bacteria and archaea), the cell cycle is divided into the B, C, and D periods. The B period extends from the end of cell division to the beginning of DNA replication. DNA replication occurs during the C period. The D period refers to the stage between the end of DNA replication and the splitting of the bacterial cell into two daughter cells. In single-celled organisms, a single cell-division cycle is how the organism reproduces. In multicellular organisms such as plants and animals, a series of cell-division cycles is how the organism develops from a single-celled fertilized egg into a mature organism, and is also the process by which hair, skin, blood cells, and some internal organs are regenerated and healed (with the possible exception of nerves; see nerve damage). After cell division, each of the daughter cells begins the interphase of a new cell cycle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle: Eukaryotic phases', 'The eukaryotic cell cycle consists of four distinct phases: G1 phase, S phase (synthesis), G2 phase (collectively known as interphase) and M phase (mitosis and cytokinesis). M phase is itself composed of two tightly coupled processes: mitosis, in which the cell''s nucleus divides, and cytokinesis, in which the cell''s cytoplasm and cell membrane divides forming two daughter cells. Activation of each phase is dependent on the proper progression and completion of the previous one. Cells that have temporarily or reversibly stopped dividing are said to have entered a state of quiescence known as G0 phase or resting phase.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The eukaryotic cell cycle consists of four distinct phases: G1 phase, S phase (synthesis), G2 phase (collectively known as interphase) and M phase (mitosis and cytokinesis). M phase is itself composed of two tightly coupled processes: mitosis, in which the cell''s nucleus divides, and cytokinesis, in which the cell''s cytoplasm and cell membrane divides forming two daughter cells. Activation of each phase is dependent on the proper progression and completion of the previous one. Cells that have temporarily or reversibly stopped dividing are said to have entered a state of quiescence known as G0 phase or resting phase.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle: G0 phase (quiescence)', 'G0 is a resting phase where the cell has left the cycle and has stopped dividing. The cell cycle starts with this phase. Non-proliferative (non-dividing) cells in multicellular eukaryotes generally enter the quiescent G0 state from G1 and may remain quiescent for long periods of time, possibly indefinitely (as is often the case for neurons). This is very common for cells that are fully differentiated. Some cells enter the G0 phase semi-permanently and are considered post-mitotic, e.g., some liver, kidney, and stomach cells. Many cells do not enter G0 and continue to divide throughout an organism''s life, e.g., epithelial cells. The word "post-mitotic" is sometimes used to refer to both quiescent and senescent cells. Cellular senescence occurs in response to DNA damage and external stress and usually constitutes an arrest in G1. Cellular senescence may make a cell''s progeny nonviable; it is often a biochemical alternative to the self-destruction of such a damaged cell by apoptosis.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'G0 is a resting phase where the cell has left the cycle and has stopped dividing. The cell cycle starts with this phase. Non-proliferative (non-dividing) cells in multicellular eukaryotes generally enter the quiescent G0 state from G1 and may remain quiescent for long periods of time, possibly indefinitely (as is often the case for neurons). This is very common for cells that are fully differentiated. Some cells enter the G0 phase semi-permanently and are considered post-mitotic, e.g., some liver, kidney, and stomach cells. Many cells do not enter G0 and continue to divide throughout an organism''s life, e.g., epithelial cells. The word "post-mitotic" is sometimes used to refer to both quiescent and senescent cells. Cellular senescence occurs in response to DNA damage and external stress and usually constitutes an arrest in G1. Cellular senescence may make a cell''s progeny nonviable; it is often a biochemical alternative to the self-destruction of such a damaged cell by apoptosis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle: Interphase', 'Interphase represents the phase between two successive M phases. Interphase is a series of changes that takes place in a newly formed cell and its nucleus before it becomes capable of division again. It is also called preparatory phase or intermitosis. Typically interphase lasts for at least 91% of the total time required for the cell cycle. Interphase proceeds in three stages, G1, S, and G2, followed by the cycle of mitosis and cytokinesis. The cell''s nuclear DNA contents are duplicated during S phase.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Interphase represents the phase between two successive M phases. Interphase is a series of changes that takes place in a newly formed cell and its nucleus before it becomes capable of division again. It is also called preparatory phase or intermitosis. Typically interphase lasts for at least 91% of the total time required for the cell cycle. Interphase proceeds in three stages, G1, S, and G2, followed by the cycle of mitosis and cytokinesis. The cell''s nuclear DNA contents are duplicated during S phase.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle: G1 phase (First growth phase or Post mitotic gap phase)', 'The first phase within interphase, from the end of the previous M phase until the beginning of DNA synthesis, is called G1 (G indicating gap). It is also called the growth phase. During this phase, the biosynthetic activities of the cell, which are considerably slowed down during M phase, resume at a high rate. The duration of G1 is highly variable, even among different cells of the same species. In this phase, the cell increases its supply of proteins, increases the number of organelles (such as mitochondria, ribosomes), and grows in size. In G1 phase, a cell has three options. Become arrested in G1 phase hence it may enter G0 phase or re-enter cell cycle. The deciding point is called check point (Restriction point). This check point is called the restriction point or START and is regulated by G1/S cyclins, which cause transition from G1 to S phase. Passage through the G1 check point commits the cell to division.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The first phase within interphase, from the end of the previous M phase until the beginning of DNA synthesis, is called G1 (G indicating gap). It is also called the growth phase. During this phase, the biosynthetic activities of the cell, which are considerably slowed down during M phase, resume at a high rate. The duration of G1 is highly variable, even among different cells of the same species. In this phase, the cell increases its supply of proteins, increases the number of organelles (such as mitochondria, ribosomes), and grows in size. In G1 phase, a cell has three options. Become arrested in G1 phase hence it may enter G0 phase or re-enter cell cycle. The deciding point is called check point (Restriction point). This check point is called the restriction point or START and is regulated by G1/S cyclins, which cause transition from G1 to S phase. Passage through the G1 check point commits the cell to division.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle: S phase (DNA replication)', 'The ensuing S phase starts when DNA synthesis commences; when it is complete, all of the chromosomes have been replicated, i.e., each chromosome consists of two sister chromatids. Thus, during this phase, the amount of DNA in the cell has doubled, though the ploidy and number of chromosomes are unchanged. Rates of RNA transcription and protein synthesis are very low during this phase. An exception to this is histone production, most of which occurs during the S phase.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The ensuing S phase starts when DNA synthesis commences; when it is complete, all of the chromosomes have been replicated, i.e., each chromosome consists of two sister chromatids. Thus, during this phase, the amount of DNA in the cell has doubled, though the ploidy and number of chromosomes are unchanged. Rates of RNA transcription and protein synthesis are very low during this phase. An exception to this is histone production, most of which occurs during the S phase.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Cell cycle: G2 phase (growth)', 'G2 phase occurs after DNA replication and is a period of protein synthesis and rapid cell growth to prepare the cell for mitosis. During this phase microtubules begin to reorganize to form a spindle (preprophase). Before proceeding to mitotic phase, cells must be checked at the G2 checkpoint for any DNA damage within the chromosomes. The G2 checkpoint is mainly regulated by the tumor protein p53. If the DNA is damaged, p53 will either repair the DNA or trigger the apoptosis of the cell. If p53 is dysfunctional or mutated, cells with damaged DNA may continue through the cell cycle, leading to the development of cancer.', 'Wikipedia: Cell cycle', 'https://en.wikipedia.org/w/index.php?title=Cell_cycle&oldid=1371110776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'G2 phase occurs after DNA replication and is a period of protein synthesis and rapid cell growth to prepare the cell for mitosis. During this phase microtubules begin to reorganize to form a spindle (preprophase). Before proceeding to mitotic phase, cells must be checked at the G2 checkpoint for any DNA damage within the chromosomes. The G2 checkpoint is mainly regulated by the tumor protein p53. If the DNA is damaged, p53 will either repair the DNA or trigger the apoptosis of the cell. If p53 is dysfunctional or mutated, cells with damaged DNA may continue through the cell cycle, leading to the development of cancer.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis', 'Mitosis () is a part of the cell cycle in eukaryotic cells in which replicated chromosomes are separated into two new nuclei. Cell division by mitosis is an equational division which gives rise to genetically identical cells in which the total number of chromosomes is maintained. Mitosis is preceded by the S phase of interphase (during which DNA replication occurs) and is followed by telophase and cytokinesis, which divide the cytoplasm, organelles, and cell membrane of one cell into two new cells containing roughly equal shares of these cellular components. This process ensures that each daughter cell receives an identical set of chromosomes, maintaining genetic stability across cell generations. The different stages of mitosis altogether define the mitotic phase (M phase) of a cell cycle—the division of the mother cell into two daughter cells genetically identical to each other.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Mitosis () is a part of the cell cycle in eukaryotic cells in which replicated chromosomes are separated into two new nuclei. Cell division by mitosis is an equational division which gives rise to genetically identical cells in which the total number of chromosomes is maintained. Mitosis is preceded by the S phase of interphase (during which DNA replication occurs) and is followed by telophase and cytokinesis, which divide the cytoplasm, organelles, and cell membrane of one cell into two new cells containing roughly equal shares of these cellular components. This process ensures that each daughter cell receives an identical set of chromosomes, maintaining genetic stability across cell generations. The different stages of mitosis altogether define the mitotic phase (M phase) of a cell cycle—the division of the mother cell into two daughter cells genetically identical to each other.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis', 'The process of mitosis is divided into stages corresponding to the completion of one set of activities and the start of the next. These stages are preprophase (specific to plant cells), prophase, prometaphase, metaphase, anaphase, and telophase. During mitosis, the chromosomes, which have already duplicated during interphase, condense and attach to spindle fibers that pull one copy of each chromosome to opposite sides of the cell. The result is two genetically identical daughter nuclei. The rest of the cell may then continue to divide by cytokinesis to produce two daughter cells. The different phases of mitosis can be visualized in real time, using live cell imaging. An error in mitosis can result in the production of three or more daughter cells instead of the normal two. This is called tripolar mitosis and multipolar mitosis, respectively. These errors can be the cause of non-viable embryos that fail to implant. Other errors during mitosis can induce mitotic catastrophe, apoptosis (programmed cell death) or cause mutations. Certain types of cancers can arise from such mutations.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The process of mitosis is divided into stages corresponding to the completion of one set of activities and the start of the next. These stages are preprophase (specific to plant cells), prophase, prometaphase, metaphase, anaphase, and telophase. During mitosis, the chromosomes, which have already duplicated during interphase, condense and attach to spindle fibers that pull one copy of each chromosome to opposite sides of the cell. The result is two genetically identical daughter nuclei. The rest of the cell may then continue to divide by cytokinesis to produce two daughter cells. The different phases of mitosis can be visualized in real time, using live cell imaging. An error in mitosis can result in the production of three or more daughter cells instead of the normal two. This is called tripolar mitosis and multipolar mitosis, respectively. These errors can be the cause of non-viable embryos that fail to implant. Other errors during mitosis can induce mitotic catastrophe, apoptosis (programmed cell death) or cause mutations. Certain types of cancers can arise from such mutations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis', 'Mitosis varies between organisms. For example, animal cells generally undergo an open mitosis, where the nuclear envelope breaks down before the chromosomes separate, whereas fungal cells generally undergo a closed mitosis, where chromosomes divide within an intact cell nucleus. Most animal cells undergo a shape change, known as mitotic cell rounding, to adopt a near spherical morphology at the start of mitosis. Most human cells are produced by mitotic cell division. Important exceptions include the gametes – sperm and egg cells – which are produced by meiosis. Prokaryotes, bacteria and archaea which lack a true nucleus, divide by a different process called binary fission.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Mitosis varies between organisms. For example, animal cells generally undergo an open mitosis, where the nuclear envelope breaks down before the chromosomes separate, whereas fungal cells generally undergo a closed mitosis, where chromosomes divide within an intact cell nucleus. Most animal cells undergo a shape change, known as mitotic cell rounding, to adopt a near spherical morphology at the start of mitosis. Most human cells are produced by mitotic cell division. Important exceptions include the gametes – sperm and egg cells – which are produced by meiosis. Prokaryotes, bacteria and archaea which lack a true nucleus, divide by a different process called binary fission.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis: Discovery', 'Numerous descriptions of cell division were made during 18th and 19th centuries, with various degrees of accuracy. In 1835, the German botanist Hugo von Mohl, described cell division in the green algae Cladophora glomerata, stating that multiplication of cells occurs through cell division. In 1838, Matthias Jakob Schleiden affirmed that "formation of new cells in their interior was a general rule for cell multiplication in plants", a view later rejected in favour of Mohl''s model, due to contributions of Robert Remak and others. In animal cells, cell division with mitosis was discovered in frog, rabbit, and cat cornea cells in 1873 and described for the first time by the Polish histologist Wacław Mayzel in 1875. Bütschli, Schneider and Fol might have also claimed the discovery of the process presently known as "mitosis". In 1873, the German zoologist Otto Bütschli published data from observations on nematodes. A few years later, he discovered and described mitosis based on those observations.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Numerous descriptions of cell division were made during 18th and 19th centuries, with various degrees of accuracy. In 1835, the German botanist Hugo von Mohl, described cell division in the green algae Cladophora glomerata, stating that multiplication of cells occurs through cell division. In 1838, Matthias Jakob Schleiden affirmed that "formation of new cells in their interior was a general rule for cell multiplication in plants", a view later rejected in favour of Mohl''s model, due to contributions of Robert Remak and others. In animal cells, cell division with mitosis was discovered in frog, rabbit, and cat cornea cells in 1873 and described for the first time by the Polish histologist Wacław Mayzel in 1875. Bütschli, Schneider and Fol might have also claimed the discovery of the process presently known as "mitosis". In 1873, the German zoologist Otto Bütschli published data from observations on nematodes. A few years later, he discovered and described mitosis based on those observations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis: Discovery', 'The term "mitosis", coined by Walther Flemming in 1882, is derived from the Greek word μίτος (mitos, "warp thread"). There are some alternative names for the process, e.g., "karyokinesis" (nuclear division), a term introduced by Schleicher in 1878, or "equational division", proposed by August Weismann in 1887. However, the term "mitosis" is also used in a broad sense by some authors to refer to karyokinesis and cytokinesis together. Presently, "equational division" is more commonly used to refer to meiosis II, the part of meiosis most like mitosis.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The term "mitosis", coined by Walther Flemming in 1882, is derived from the Greek word μίτος (mitos, "warp thread"). There are some alternative names for the process, e.g., "karyokinesis" (nuclear division), a term introduced by Schleicher in 1878, or "equational division", proposed by August Weismann in 1887. However, the term "mitosis" is also used in a broad sense by some authors to refer to karyokinesis and cytokinesis together. Presently, "equational division" is more commonly used to refer to meiosis II, the part of meiosis most like mitosis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis: Overview', 'The primary result of mitosis and cytokinesis is the transfer of a parent cell''s genome into two daughter cells. The genome is composed of a number of chromosomes—complexes of tightly coiled DNA that contain genetic information vital for proper cell function. Because each resultant daughter cell should be genetically identical to the parent cell, the parent cell must make a copy of each chromosome before mitosis. This occurs during the S phase of interphase. Chromosome duplication results in two identical sister chromatids bound together by cohesin proteins at the centromere. When mitosis begins, the chromosomes condense and become visible. In some eukaryotes, for example animals, the nuclear envelope, which segregates the DNA from the cytoplasm, disintegrates into small vesicles. The nucleolus, which makes ribosomes in the cell, also disappears. Microtubules project from opposite ends of the cell, attach to the centromeres, and align the chromosomes centrally within the cell. The microtubules then contract to pull the sister chromatids of each chromosome apart. Sister chromatids at this point are called daughter chromosomes. As the cell elongates, corresponding daughter chromosomes are pulled toward opposite ends of the cell and condense maximally in late anaphase. A new nuclear envelope forms around each set of daughter chromosomes, which decondense to form interphase nuclei.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The primary result of mitosis and cytokinesis is the transfer of a parent cell''s genome into two daughter cells. The genome is composed of a number of chromosomes—complexes of tightly coiled DNA that contain genetic information vital for proper cell function. Because each resultant daughter cell should be genetically identical to the parent cell, the parent cell must make a copy of each chromosome before mitosis. This occurs during the S phase of interphase. Chromosome duplication results in two identical sister chromatids bound together by cohesin proteins at the centromere. When mitosis begins, the chromosomes condense and become visible. In some eukaryotes, for example animals, the nuclear envelope, which segregates the DNA from the cytoplasm, disintegrates into small vesicles. The nucleolus, which makes ribosomes in the cell, also disappears. Microtubules project from opposite ends of the cell, attach to the centromeres, and align the chromosomes centrally within the cell. The microtubules then contract to pull the sister chromatids of each chromosome apart. Sister chromatids at this point are called daughter chromosomes. As the cell elongates, corresponding daughter chromosomes are pulled toward opposite ends of the cell and condense maximally in late anaphase. A new nuclear envelope forms around each set of daughter chromosomes, which decondense to form interphase nuclei.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis: Overview', 'During mitotic progression, typically after the anaphase onset, the cell may undergo cytokinesis. In animal cells, a cell membrane pinches inward between the two developing nuclei to produce two new cells. In plant cells, a cell plate forms between the two nuclei. Cytokinesis does not always occur; coenocytic (a type of multinucleate condition) cells undergo mitosis without cytokinesis.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'During mitotic progression, typically after the anaphase onset, the cell may undergo cytokinesis. In animal cells, a cell membrane pinches inward between the two developing nuclei to produce two new cells. In plant cells, a cell plate forms between the two nuclei. Cytokinesis does not always occur; coenocytic (a type of multinucleate condition) cells undergo mitosis without cytokinesis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Mitosis: Interphase', 'The interphase is a much longer phase of the cell cycle than the relatively short M phase. During interphase the cell prepares itself for the process of cell division. Interphase is divided into three subphases: G1 (first gap), S (synthesis), and G2 (second gap). During all three parts of interphase, the cell grows by producing proteins and cytoplasmic organelles. However, chromosomes are replicated only during the S phase. Thus, a cell grows (G1), continues to grow as it duplicates its chromosomes (S), grows more and prepares for mitosis (G2), and finally divides (M) before restarting the cycle. All these phases in the cell cycle are highly regulated by cyclins, cyclin-dependent kinases, and other cell cycle proteins. The phases follow one another in strict order and there are cell cycle checkpoints that give the cell cues to proceed or not, from one phase to another. Cells may also temporarily or permanently leave the cell cycle and enter G0 phase to stop dividing. This can occur when cells become overcrowded (density-dependent inhibition) or when they differentiate to carry out specific functions for the organism, as is the case for human heart muscle cells and neurons. Some G0 cells have the ability to re-enter the cell cycle.', 'Wikipedia: Mitosis', 'https://en.wikipedia.org/w/index.php?title=Mitosis&oldid=1380696988', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'The interphase is a much longer phase of the cell cycle than the relatively short M phase. During interphase the cell prepares itself for the process of cell division. Interphase is divided into three subphases: G1 (first gap), S (synthesis), and G2 (second gap). During all three parts of interphase, the cell grows by producing proteins and cytoplasmic organelles. However, chromosomes are replicated only during the S phase. Thus, a cell grows (G1), continues to grow as it duplicates its chromosomes (S), grows more and prepares for mitosis (G2), and finally divides (M) before restarting the cycle. All these phases in the cell cycle are highly regulated by cyclins, cyclin-dependent kinases, and other cell cycle proteins. The phases follow one another in strict order and there are cell cycle checkpoints that give the cell cues to proceed or not, from one phase to another. Cells may also temporarily or permanently leave the cell cycle and enter G0 phase to stop dividing. This can occur when cells become overcrowded (density-dependent inhibition) or when they differentiate to carry out specific functions for the organism, as is the case for human heart muscle cells and neurons. Some G0 cells have the ability to re-enter the cell cycle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis', 'Meiosis ( ) is a special type of cell division of germ cells in sexually-reproducing organisms that produces the gametes: the sperm or egg cells. It involves two rounds of division that ultimately result in four cells, each with only one copy of each chromosome (haploid). Additionally, prior to the division, genetic material from the paternal and maternal copies of each chromosome is crossed over, creating new combinations of code on each chromosome. Later on, during fertilisation, the haploid cells produced by meiosis from a male and a female will fuse to create a zygote, a cell with two copies of each chromosome. In mammals, the process of meiosis finishes only after fertilization so the product is a zygote. Errors in meiosis resulting in aneuploidy (an abnormal number of chromosomes) are the leading known cause of miscarriage and the most frequent genetic cause of developmental disabilities.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Meiosis ( ) is a special type of cell division of germ cells in sexually-reproducing organisms that produces the gametes: the sperm or egg cells. It involves two rounds of division that ultimately result in four cells, each with only one copy of each chromosome (haploid). Additionally, prior to the division, genetic material from the paternal and maternal copies of each chromosome is crossed over, creating new combinations of code on each chromosome. Later on, during fertilisation, the haploid cells produced by meiosis from a male and a female will fuse to create a zygote, a cell with two copies of each chromosome. In mammals, the process of meiosis finishes only after fertilization so the product is a zygote. Errors in meiosis resulting in aneuploidy (an abnormal number of chromosomes) are the leading known cause of miscarriage and the most frequent genetic cause of developmental disabilities.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis', 'In meiosis, DNA replication is followed by two rounds of cell division to produce four daughter cells, each with half the number of chromosomes as the original parent cell. The two meiotic divisions are known as meiosis I and meiosis II. Before meiosis begins, during S phase of the cell cycle, the DNA of each chromosome is replicated so that it consists of two identical sister chromatids, which remain held together through sister chromatid cohesion. This S-phase can be referred to as "premeiotic S-phase" or "meiotic S-phase". Immediately following DNA replication, meiotic cells enter a prolonged G2-like stage known as meiotic prophase. During this time, homologous chromosomes pair with each other and undergo genetic recombination, a programmed process in which DNA may be cut and then repaired, which allows them to exchange some of their genetic information. A subset of recombination events results in crossovers, which create physical links known as chiasmata (singular: chiasma, for the Greek letter Chi, Χ) between the homologous chromosomes. In most organisms, these links can help direct each pair of homologous chromosomes to segregate away from each other during meiosis II, resulting in two haploid cells that have half the number of chromosomes as the parent cell.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'In meiosis, DNA replication is followed by two rounds of cell division to produce four daughter cells, each with half the number of chromosomes as the original parent cell. The two meiotic divisions are known as meiosis I and meiosis II. Before meiosis begins, during S phase of the cell cycle, the DNA of each chromosome is replicated so that it consists of two identical sister chromatids, which remain held together through sister chromatid cohesion. This S-phase can be referred to as "premeiotic S-phase" or "meiotic S-phase". Immediately following DNA replication, meiotic cells enter a prolonged G2-like stage known as meiotic prophase. During this time, homologous chromosomes pair with each other and undergo genetic recombination, a programmed process in which DNA may be cut and then repaired, which allows them to exchange some of their genetic information. A subset of recombination events results in crossovers, which create physical links known as chiasmata (singular: chiasma, for the Greek letter Chi, Χ) between the homologous chromosomes. In most organisms, these links can help direct each pair of homologous chromosomes to segregate away from each other during meiosis II, resulting in two haploid cells that have half the number of chromosomes as the parent cell.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis', 'During meiosis II, the cohesion between sister chromatids is released and they segregate from one another, as during mitosis. In some cases, all four of the meiotic products form gametes such as sperm, spores or pollen. In female animals, three of the four meiotic products are typically eliminated by extrusion into polar bodies, and only one cell develops to produce an ovum. Because the number of chromosomes is halved during meiosis, gametes can fuse (i.e., fertilization) to form a diploid zygote that contains two copies of each chromosome, one from each parent. Thus, alternating cycles of meiosis and fertilization enable sexual reproduction, with successive generations maintaining the same number of chromosomes. For example, diploid human cells contain 23 pairs of chromosomes including 1 pair of sex chromosomes (46 total), half of maternal origin and half of paternal origin. Meiosis produces haploid gametes (ova or sperm) that contain one set of 23 chromosomes. When two gametes (an egg and a sperm) fuse, the resulting zygote is once again diploid, with the mother and father each contributing 23 chromosomes. This same pattern, but not the same number of chromosomes, occurs in all organisms that utilize meiosis.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'During meiosis II, the cohesion between sister chromatids is released and they segregate from one another, as during mitosis. In some cases, all four of the meiotic products form gametes such as sperm, spores or pollen. In female animals, three of the four meiotic products are typically eliminated by extrusion into polar bodies, and only one cell develops to produce an ovum. Because the number of chromosomes is halved during meiosis, gametes can fuse (i.e., fertilization) to form a diploid zygote that contains two copies of each chromosome, one from each parent. Thus, alternating cycles of meiosis and fertilization enable sexual reproduction, with successive generations maintaining the same number of chromosomes. For example, diploid human cells contain 23 pairs of chromosomes including 1 pair of sex chromosomes (46 total), half of maternal origin and half of paternal origin. Meiosis produces haploid gametes (ova or sperm) that contain one set of 23 chromosomes. When two gametes (an egg and a sperm) fuse, the resulting zygote is once again diploid, with the mother and father each contributing 23 chromosomes. This same pattern, but not the same number of chromosomes, occurs in all organisms that utilize meiosis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis', 'Meiosis occurs in all sexually reproducing single-celled and multicellular organisms (which are all eukaryotes), including animals, plants, and fungi. It is an essential process for oogenesis and spermatogenesis.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Meiosis occurs in all sexually reproducing single-celled and multicellular organisms (which are all eukaryotes), including animals, plants, and fungi. It is an essential process for oogenesis and spermatogenesis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis: Overview', 'Although the process of meiosis is related to the more general cell division process of mitosis, it differs in two important respects: Meiosis begins with a diploid cell, which contains two copies of each chromosome, termed homologs. First, the cell undergoes DNA replication, so each homolog now consists of two identical sister chromatids. Then each set of homologs pair with each other and exchange genetic information by homologous recombination often leading to physical connections (crossovers) between the homologs. In the first meiotic division, the homologs are segregated to separate daughter cells by the spindle apparatus. The cells then proceed to a second division without an intervening round of DNA replication. The sister chromatids are segregated to separate daughter cells to produce a total of four haploid cells. Female animals employ a slight variation on this pattern and produce one large ovum and three small polar bodies. Because of recombination, an individual chromatid can consist of a new combination of maternal and paternal genetic information, resulting in offspring that are genetically distinct from either parent. Furthermore, an individual gamete can include an assortment of maternal, paternal, and recombinant chromatids. This genetic diversity resulting from sexual reproduction contributes to the variation in traits upon which natural selection can act.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Although the process of meiosis is related to the more general cell division process of mitosis, it differs in two important respects: Meiosis begins with a diploid cell, which contains two copies of each chromosome, termed homologs. First, the cell undergoes DNA replication, so each homolog now consists of two identical sister chromatids. Then each set of homologs pair with each other and exchange genetic information by homologous recombination often leading to physical connections (crossovers) between the homologs. In the first meiotic division, the homologs are segregated to separate daughter cells by the spindle apparatus. The cells then proceed to a second division without an intervening round of DNA replication. The sister chromatids are segregated to separate daughter cells to produce a total of four haploid cells. Female animals employ a slight variation on this pattern and produce one large ovum and three small polar bodies. Because of recombination, an individual chromatid can consist of a new combination of maternal and paternal genetic information, resulting in offspring that are genetically distinct from either parent. Furthermore, an individual gamete can include an assortment of maternal, paternal, and recombinant chromatids. This genetic diversity resulting from sexual reproduction contributes to the variation in traits upon which natural selection can act.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis: Overview', 'Meiosis uses many of the same mechanisms as mitosis, the type of cell division used by eukaryotes to divide one cell into two identical daughter cells. In some plants, fungi, and protists meiosis results in the formation of spores: haploid cells that can divide vegetatively without undergoing fertilization. Some eukaryotes, like bdelloid rotifers, do not have the ability to carry out meiosis and have acquired the ability to reproduce by parthenogenesis. Meiosis does not occur in archaea or bacteria, which generally reproduce asexually via binary fission. However, a "sexual" process known as horizontal gene transfer involves the transfer of DNA from one bacterium or archaeon to another and recombination of these DNA molecules of different parental origin.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Meiosis uses many of the same mechanisms as mitosis, the type of cell division used by eukaryotes to divide one cell into two identical daughter cells. In some plants, fungi, and protists meiosis results in the formation of spores: haploid cells that can divide vegetatively without undergoing fertilization. Some eukaryotes, like bdelloid rotifers, do not have the ability to carry out meiosis and have acquired the ability to reproduce by parthenogenesis. Meiosis does not occur in archaea or bacteria, which generally reproduce asexually via binary fission. However, a "sexual" process known as horizontal gene transfer involves the transfer of DNA from one bacterium or archaeon to another and recombination of these DNA molecules of different parental origin.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis: Phases', 'Meiosis is divided into meiosis I and meiosis II which are further divided into Karyokinesis I, Cytokinesis I, Karyokinesis II, and Cytokinesis II, respectively. The preparatory steps that lead up to meiosis are identical in pattern and name to interphase of the mitotic cell cycle. Interphase is divided into three phases: Growth 1 (G1) phase: In this very active phase, the cell synthesizes its vast array of proteins, including the enzymes and structural proteins it will need for growth. In G1, each of the chromosomes consists of a single linear molecule of DNA. Synthesis (S) phase: The genetic material is replicated; each of the cell''s chromosomes duplicates to become two identical sister chromatids attached at a centromere. This replication does not change the ploidy of the cell since the centromere number remains the same. The identical sister chromatids have not yet condensed into the densely packaged chromosomes visible with the light microscope. This will take place during prophase I in meiosis. Growth 2 (G2) phase: G2 phase as seen before mitosis is not present in meiosis. Meiotic prophase corresponds most closely to the G2 phase of the mitotic cell cycle.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Meiosis is divided into meiosis I and meiosis II which are further divided into Karyokinesis I, Cytokinesis I, Karyokinesis II, and Cytokinesis II, respectively. The preparatory steps that lead up to meiosis are identical in pattern and name to interphase of the mitotic cell cycle. Interphase is divided into three phases: Growth 1 (G1) phase: In this very active phase, the cell synthesizes its vast array of proteins, including the enzymes and structural proteins it will need for growth. In G1, each of the chromosomes consists of a single linear molecule of DNA. Synthesis (S) phase: The genetic material is replicated; each of the cell''s chromosomes duplicates to become two identical sister chromatids attached at a centromere. This replication does not change the ploidy of the cell since the centromere number remains the same. The identical sister chromatids have not yet condensed into the densely packaged chromosomes visible with the light microscope. This will take place during prophase I in meiosis. Growth 2 (G2) phase: G2 phase as seen before mitosis is not present in meiosis. Meiotic prophase corresponds most closely to the G2 phase of the mitotic cell cycle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'cells-membranes', 'Meiosis: Phases', 'Interphase is followed by meiosis I and then meiosis II. Meiosis I separates replicated homologous chromosomes, each still made up of two sister chromatids, into two daughter cells, thus reducing the chromosome number by half. During meiosis II, sister chromatids decouple, and the resultant daughter chromosomes are segregated into four daughter cells. For diploid organisms, the daughter cells resulting from meiosis are haploid and contain only one copy of each chromosome. In some species, cells enter a resting phase known as interkinesis between meiosis I and meiosis II. Meiosis I and II are each divided into prophase, metaphase, anaphase, and telophase stages, similar in purpose to their analogous subphases in the mitotic cell cycle. Therefore, meiosis includes the stages of meiosis I (prophase I, metaphase I, anaphase I, telophase I) and meiosis II (prophase II, metaphase II, anaphase II, telophase II). During meiosis, specific genes are more highly transcribed. In addition to strong meiotic stage-specific expression of mRNA, there are also pervasive translational controls (e.g. selective usage of preformed mRNA), regulating the ultimate meiotic stage-specific protein expression of genes during meiosis. Thus, both transcriptional and translational conttrols determine the broad restructuring of meiotic cells needed to carry out meiosis.', 'Wikipedia: Meiosis', 'https://en.wikipedia.org/w/index.php?title=Meiosis&oldid=1381235514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'cells-membranes' and body = 'Interphase is followed by meiosis I and then meiosis II. Meiosis I separates replicated homologous chromosomes, each still made up of two sister chromatids, into two daughter cells, thus reducing the chromosome number by half. During meiosis II, sister chromatids decouple, and the resultant daughter chromosomes are segregated into four daughter cells. For diploid organisms, the daughter cells resulting from meiosis are haploid and contain only one copy of each chromosome. In some species, cells enter a resting phase known as interkinesis between meiosis I and meiosis II. Meiosis I and II are each divided into prophase, metaphase, anaphase, and telophase stages, similar in purpose to their analogous subphases in the mitotic cell cycle. Therefore, meiosis includes the stages of meiosis I (prophase I, metaphase I, anaphase I, telophase I) and meiosis II (prophase II, metaphase II, anaphase II, telophase II). During meiosis, specific genes are more highly transcribed. In addition to strong meiotic stage-specific expression of mRNA, there are also pervasive translational controls (e.g. selective usage of preformed mRNA), regulating the ultimate meiotic stage-specific protein expression of genes during meiosis. Thus, both transcriptional and translational conttrols determine the broad restructuring of meiotic cells needed to carry out meiosis.');
